/** Every slash command the registry declares. */
export const COMMANDS = commandsOf(names.map((name) => [name, entryOf(name)]));
const RANKS = { anyone: 0, guest: 1, member: 2, maintainer: 3, admin: 4 };
/** What a viewer counts as: anyone when signed out, a Guest when signed in with no role (decision 0007 §1), else the role. */
export const rankOf = (viewer) => (viewer.signedIn ? RANKS[viewer.role ?? "guest"] : RANKS.anyone);
/** The commands `viewer` may run, of `commands`. */
export const commandsFor = (viewer, commands = COMMANDS) => commands.filter((command) => rankOf(viewer) >= RANKS[command.minimum]);
